\documentclass{article}
\usepackage{amsmath}
\usepackage{pgfplots}
\usepackage{tikz}
\usepackage{tikz-3dplot}
\usetikzlibrary{arrows}
\usetikzlibrary{positioning}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}
\usepackage{tkz-euclide}
\usepackage{ifthen}
\usetkzobj{all}

% Builds a rectangular tile
% params: {tile-lenght}{tile-higt}{color}{shift}{rotate}
\newcommand{\myRecTile}[5]{
    \begin{scope}[shift={#4}]
    	\coordinate (A) at (0,0,0);
    		\pgfmathsetmacro{\xc}{#1*cos(-#5)+0*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+0*cos(-#5)};
		\coordinate (B) at (\xc,0,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+#2*cos(-#5)};
	    \coordinate (C) at (\xc,0,\yc);
			\pgfmathsetmacro{\xc}{0*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-0*sin(-#5)+#2*cos(-#5)};
	    \coordinate (D) at (\xc,0,\yc);    	

    	\tkzDrawPolygon[very thick, color=#3, fill = #3!15](A,B,C,D)	 
    \end{scope}   
}


% Builds a triangular tile
% params: {tile-lenght}{tile-higt}{color}{shift}{rotate}
\newcommand{\myTriagTile}[5]{
    \begin{scope}[shift={#4}]
    	\coordinate (A) at (0,0,0);
    		\pgfmathsetmacro{\xc}{#1*cos(-#5)+0*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+0*cos(-#5)};
		\coordinate (B) at (\xc,0,\yc);
			\pgfmathsetmacro{\xc}{#1/2*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1/2*sin(-#5)+#2*cos(-#5)};
	    \coordinate (C) at (\xc,0,\yc);

    	\tkzDrawPolygon[very thick, color=#3, fill = #3!15](A,B,C)	 
    \end{scope}  
}

% Builds a triangular pyramid net
% params: {color}
\newcommand{\myTrigPrismNet}[1]{ 

	\def\a{2}
	\def\h{3}

	\myRecTile{\a}{1.5*\a}{#1}{(0,0,0)}{0};   
	\myTriagTile{1.5*\a}{\h}{#1}{(0,0,0)}{90};  
	\myTriagTile{1.5*\a}{\h}{#1}{(\a,0,1.5*\a)}{-90};  
	\myTriagTile{\a}{1.05*\h}{#1}{(0,0,1.5*\a)}{135};    
        \myTriagTile{\a}{\h}{#1}{(\a,0,0)}{180};   

	\draw[ ->, dashed, thick, gray] (-1,0,1)  to [bend left=50] (0,1,1);
	\draw[ ->, dashed, thick, gray] (3,0,1)  to [bend right=50] (2,1,1);
	\draw[ ->, dashed, thick, gray] (-1.5,0,3)  to [bend left=30] (-1.5,1,2);
	\draw[ ->, dashed, thick, gray] (1,0,-1)  to [bend right=30] (1,1,0);  

}

