\newcommand{\myRecPyramid}[6]{ 
	\begin{scope}[scale=#6]
		\coordinate (A) at (0,0,0);
		\coordinate (B) at (#1,0,0);
		\coordinate (C) at (#1,0,-#2);
		\coordinate (D) at (0,0,-#2);
		\coordinate (S) at (#1/2-0.5,#3/2,-#2);  

		% Faces
		\tkzDrawPolygon[draw=none, fill=#4!15, fill opacity=#5](A,B,S)
		\tkzDrawPolygon[draw=none, fill=#4!15, fill opacity=#5](B,C,S)
		\tkzDrawPolygon[draw=none, fill=#4!15, fill opacity=#5](C,D,S)
		\tkzDrawPolygon[draw=none, fill=#4!15, fill opacity=#5](D,A,S)

		% Base
		\tkzDrawPolygon[draw=none, fill=#4!25, fill opacity=#5](A,B,C,D)

		% Edges
		\tkzDrawSegments[thin, color=#4, dashed, opacity=0.5](A,D C,D D,S)
		\tkzDrawSegments[very thick, color=#4](A,B B,C A,S B,S C,S)

