\newcommand{\myRecTile}[5]{
    \begin{scope}[shift={#4}]
    	\coordinate (A) at (0,0);
    		\pgfmathsetmacro{\xc}{#1*cos(-#5)+0*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+0*cos(-#5)};
		\coordinate (B) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+#2*cos(-#5)};
	    \coordinate (C) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{0*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-0*sin(-#5)+#2*cos(-#5)};
	    \coordinate (D) at (\xc,\yc);    	

    	\tkzDrawPolygon[very thick, color=#3, fill = #3!15](A,B,C,D)	 
    \end{scope}  
}

% Builds a triangular tile
% params: {tile-lenght}{tile-higt}{color}{shift}{rotate}
\newcommand{\myTriagTile}[5]{
    \begin{scope}[shift={#4}]
    	\coordinate (A) at (0,0);
    		\pgfmathsetmacro{\xc}{#1*cos(-#5)+0*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+0*cos(-#5)};
		\coordinate (B) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1/2*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1/2*sin(-#5)+#2*cos(-#5)};
	    \coordinate (C) at (\xc,\yc);

    	\tkzDrawPolygon[very thick, color=#3, fill = #3!15](A,B,C)	 

    \end{scope}  
}

% Builds cude net
% params: {color}
\newcommand{\myCubeNet}[1]{

	\myRecTile{3}{3}{#1}{(0,0)}{0};
	\myRecTile{3}{3}{#1}{(-3,0)}{0};
	\myRecTile{3}{3}{#1}{(3,0)}{0};
	\myRecTile{3}{3}{#1}{(0,3)}{0};
	\myRecTile{3}{3}{#1}{(0,-3)}{0};
	\myRecTile{3}{3}{#1}{(6,0)}{0};

}

% Builds a net
% params: {color}
\newcommand{\myTrigPrismNet}[1]{

	\def\a{2}
	\def\h{3}

	\myTriagTile{\a}{\a*0.866}{#1}{(0,0)}{0};
	\myRecTile{\a}{\h}{#1}{(0,0)}{180};
	\myRecTile{\a}{\h}{#1}{(\a,0)}{180};
	\myRecTile{\a}{\h}{#1}{(2*\a,0)}{180};
	\myTriagTile{\a}{\a*0.866}{#1}{(\a,-\h)}{180};

}

% Builds a net
% params: {color}
\newcommand{\myRecPyramidNet}[1]{

	\def\a{2}
	\def\h{4}

	\myRecTile{\a}{1.5*\a}{#1}{(0,0)}{0};

	\myTriagTile{1.5*\a}{(\h-0.2)}{#1}{(0,0)}{216};
	\myTriagTile{1.5*\a}{(\h-0.2)}{#1}{(\a,1.5*\a)}{36};

	\myTriagTile{\a}{\h}{#1}{(0,1.5*\a)}{0};
	\myTriagTile{\a}{\h}{#1}{(\a,0)}{180};
}

